// === Tab: mySketch.js ===
let palette = ['#ffff8c', '#8cffc6', '#8c8cff', '#ff8cc6'];
let vmin, vmax;
let gl, glsl;
let radius;
let depth;
let thickness;
let angle;
let h;
let NUM = 280;
let sphereArr = [];

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1416184/files/shader.vert', 'shader.frag');
}

function getTreePos(u, radius, rOffset, depth, thickness, angle) {
  let a = u * angle;
  let r = (1 - u) + rOffset;
  let v = 0.5;
  let x = cos(a) * r;
  let y = map(v + u * depth, 0, 1, 0, -1) * thickness;
  let z = sin(a) * r;
  return {
    x: x * radius,
    y: y * radius,
    z: z * radius
  }
}

function setup() {
  createCanvas(1112, 834, WEBGL);
	colorMode(HSB, 255);
  noStroke();
  gl = drawingContext;
  vmin = max(width, height);
  vmax = max(width, height);

  radius = vmin / 4;
  depth = 14;
  thickness = 0.2;
  angle = TWO_PI * 11;
  h = radius * thickness * depth;

  for (let i = 0; i < NUM; i++) {
    sphereArr[i] = getTreePos(i / NUM, radius, 0.03, depth, thickness, angle);
    Object.assign(sphereArr[i], {
      i,
      c: color(i*100%255, 255, 255)
    });
  }
}

function draw() {
  let sec = millis() / 1000;
  let ry = -sec * 0.5;

  background('#001710');

  rotateY(ry);

  gl.enable(gl.DEPTH_TEST);
  gl.depthFunc(gl.ALWAYS);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE);

  for (let { i, x, y, z, c } of sphereArr) {
    push();
    {
      translate(x, y + h / 2, z);
      rotateY(-ry);
      scale(1 + (1 - (i / NUM)) * 2);
      shader(glsl);
      glsl.setUniform('uColor', color(c)._array)
      plane(vmin / 6);
    }
    pop();
  }
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}


